WITH flattened_attrs AS (SELECT id, customer_id, created_at, coupon_codes, ship_to, attributes, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS used_spring10, SIZE(FILTER(items, li -> li.qty >= 3)) AS bulk_lines, AGGREGATE(items, 0D, (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS cart_value FROM carts) SELECT *, LAG(bulk_lines, 1) OVER (PARTITION BY YEAR(created_at), customer_id ORDER BY created_at ASC, id ASC) AS prev_bulk_lines, NTILE(4) OVER (ORDER BY bulk_lines ASC, id ASC) AS bulk_lines_bucket, LEAD(cart_value, 2) OVER (PARTITION BY customer_id ORDER BY cart_value ASC, id ASC) AS next_cart_value, SUM(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_bulk_lines, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY bulk_lines ASC) AS bulk_lines_cume_dist FROM flattened_attrs WHERE TO_DATE(created_at) < '2025-05-01';
